(()=>{'use strict';const w=(m,e)=>console.warn('[andalusi] '+m,e||'');addEventListener('error',e=>w('error',e.error||e.message));addEventListener('unhandledrejection',e=>w('rejection',e.reason));if('serviceWorker'in navigator)addEventListener('load',()=>navigator.serviceWorker.register('./andalusi-sw.js').catch(e=>w('cache',e)),{once:true})})();